#include "monitor.h"
#include <stdio.h>
MonitorResult monitor_classify(const DspFeatures *v,float current,float temp,float acoustic,float shaft){MonitorResult r={FAULT_NORMAL,HEALTH_NORMAL,0,"Signals within configured baseline."};if(current>2.0f||temp>75.0f){r.fault=FAULT_OVERLOAD;r.health=(current>3.0f||temp>90.0f)?HEALTH_CRITICAL:HEALTH_WARNING;r.severity=current/3.0f;if(temp/90.0f>r.severity)r.severity=temp/90.0f;snprintf(r.reason,sizeof(r.reason),"Current RMS %.2f A and temperature %.1f C indicate overload.",current,temp);}else if(v->high_band_energy>1.0e5f||acoustic>0.20f){r.fault=FAULT_BEARING_FAULT;r.health=HEALTH_WARNING;r.severity=0.7f;snprintf(r.reason,sizeof(r.reason),"Elevated high-band vibration/acoustic energy (%.2f).",acoustic);}else if(shaft>0&&v->dominant_hz>1.65f*shaft&&v->dominant_hz<2.35f*shaft){r.fault=FAULT_MISALIGNMENT;r.health=HEALTH_WARNING;r.severity=v->rms/(v->rms+0.15f);snprintf(r.reason,sizeof(r.reason),"Dominant component %.1f Hz is near second shaft order.",v->dominant_hz);}else if(v->rms>0.35f){r.fault=FAULT_IMBALANCE;r.health=HEALTH_WARNING;r.severity=v->rms/0.7f;snprintf(r.reason,sizeof(r.reason),"Vibration RMS %.3f g exceeds baseline.",v->rms);}return r;}
const char *fault_name(Fault f){static const char *n[]={"NORMAL","IMBALANCE","MISALIGNMENT","BEARING_FAULT","OVERLOAD"};return (unsigned)f<5?n[f]:"UNKNOWN";}
